const updateDoc = async(ref,data)=>{const key=ref.name+'/'+ref.id;if(!records.has(key))throw Error('Missing record');records.set(key,{...records.get(key),...data});};
const runTransaction = async(_,work)=>{
 const writes=[];let writing=false;
 const result=await work({get:async ref=>{if(writing)throw Error('Transaction read after write');return snap(ref);},set:(ref,data)=>{writing=true;writes.push(()=>setDoc(ref,data));},update:(ref,data)=>{writing=true;writes.push(()=>updateDoc(ref,data));},delete:ref=>{writing=true;writes.push(()=>records.delete(ref.name+'/'+ref.id));}});
 for(const apply of writes)await apply();return result;
};
