html = html.replace('</head>',`<style>${css}</style></head>`).replace('</body>',`<script type="module">${mocks}\n${strip('js/classroom-submission-policy.js')}\n${strip('js/teacher-class-policy.js')}\n${strip('js/teacher-class-client.js')}
${strip('js/teacher-support-policy.js')}
${strip('js/teacher-quiz-insights.js')}
${strip('js/teacher-report-export.js')}\n${guard}\nconst {renderTeacherHelp,renderTeacherReflectionQueue}=(()=>{${strip('js/student-feedback.js')};return {renderTeacherHelp,renderTeacherReflectionQueue};})();\n${workspace}\n${navigationHarness}\n${exercise}</script></body>`);
fs.writeFileSync(path.join(temp,'frame.html'),html);
fs.writeFileSync(path.join(temp,'index.html'),`<!doctype html><html><body><output id="result">RUNNING</output><iframe style="width:390px;height:850px" src="frame.html"></iframe><iframe style="width:1280px;height:850px" src="frame.html"></iframe><script>const results=[];addEventListener('message',e=>{if(typeof e.data==='object'&&['PASS','FAIL'].includes(e.data.state)){results.push(e.data);if(results.length===2)document.getElementById('result').textContent=JSON.stringify(results);}});</script></body></html>`);
const result = spawnSync('C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe',[
    '--headless','--disable-gpu','--no-first-run','--no-default-browser-check','--allow-file-access-from-files',
    '--user-data-dir='+path.join(temp,'browser'),'--dump-dom','--virtual-time-budget=30000','file:///'+path.join(temp,'index.html').replaceAll('\\','/')
],{encoding:'utf8',timeout:45000,maxBuffer:6*1024*1024,windowsHide:true});
if(result.error)throw result.error;
const match=result.stdout.match(/<output id="result">([^<]+)<\/output>/);
let results;try{results=JSON.parse(match?.[1].replaceAll('&amp;','&').replaceAll('&gt;','>').replaceAll('&lt;','<'));}catch{}
const pass=results?.length===2&&results.every(r=>r.state==='PASS');
const sources = ['js/auth-guard.js','js/teacher-class-policy.js','js/teacher-class-client.js','js/teacher-workspace.js','pages/teacher-dashboard.html','css/teacher-workspace.css'].map(file=>({file,sha256:createHash('sha256').update(fs.readFileSync(path.join(root,file))).digest('hex')}));
fs.writeFileSync(path.join(root,'docs/validation/teacher-workspace-browser-2026-10-31.json'),JSON.stringify({mode:'local-browser-real-modules-mocked-firestore-not-deployed',verifiedAt:new Date().toISOString(),pass,sources,results:results||match?.[1]||'No result'},null,2));
console.log(JSON.stringify({pass,results},null,2));
if(!pass){console.error(result.stderr.slice(-1200));process.exitCode=1;}
if(pass&&(process.argv.includes('--preview')||process.argv.includes('--preview-loading'))) {
    const previewSections = process.argv.includes('--preview-loading') ? ['loading'] : ['overview','classes','students','announcements','assignments','loading'];
    for (const [size,width] of [['desktop',1440],['mobile',390]]) for (const section of previewSections) {
        fs.writeFileSync(path.join(temp,'preview.html'),'<!doctype html><html><body style="margin:0;overflow:hidden"><iframe style="display:block;border:0;width:'+width+'px;height:1100px" src="frame.html?preview&tab='+section+'"></iframe></body></html>');
        const screenshot = path.join(root,'docs/validation/teacher-workspace-'+section+'-'+size+'.png');
        const preview=spawnSync('C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe',[
            '--headless','--disable-gpu','--no-first-run','--no-default-browser-check','--allow-file-access-from-files',
            '--user-data-dir='+path.join(temp,'preview-browser-'+section+'-'+size),'--window-size='+width+',1100','--screenshot='+screenshot,
            '--virtual-time-budget=10000','file:///'+path.join(temp,'preview.html').replaceAll('\\','/')
        ],{encoding:'utf8',timeout:30000,maxBuffer:1024*1024,windowsHide:true});
        if(preview.error)throw preview.error;
        if(preview.status!==0)throw Error('Preview screenshot failed');
        if(section==='overview'&&size==='desktop')fs.copyFileSync(screenshot,path.join(root,'docs/validation/teacher-workspace-local.png'));
        console.log('Preview: '+screenshot);
    }
}
